'use strict';
const groups = [{"id": "centro", "number": "01", "title": "Centro e Santo Domingo", "timing": "PICCOLE USCITE DURANTE TUTTO IL VIAGGIO", "color": "pink", "description": "Comincia vicino a casa. Una passeggiata, una chiesa e un pranzo lungo bastano per una giornata.", "sections": [["UN PO’ DI GIRI", [["alcala", "Andador Macedonio Alcalá", "via pedonale da Santo Domingo allo Zócalo"], ["zocalo", "Zócalo e Cattedrale", "piazza principale all’ombra, perfetta per guardare la gente"], ["santodomingo", "Templo de Santo Domingo", "chiesa barocca con interni scolpiti e dorati"], ["culturas", "Museo de las Culturas de Oaxaca", "storia della regione nell’ex convento accanto"], ["jardin", "Jardín Etnobotánico", "giardino di piante native e cactus", "Solo visite guidate: controlla gli orari."]]], ["MANGIARE E PRENDERSELA COMODA", [["brujula", "Café Brújula", "torrefazione locale per una pausa dopo il lavoro"], ["tlayuda", "Una tlayuda", "enorme tortilla croccante dalla griglia di strada"], ["mayordomo", "Cioccolata da Mayordomo", "cioccolato macinato a pietra, con pan de yema"], ["mole", "Mole negro a Las Quince Letras", "quello scuro al cioccolato per cui Oaxaca è famosa", "Dalla nostra lista salvata. Per un pranzo lungo."]]]], "note": "Una cosa principale e un pasto possono bastare."}, {"id": "muertos", "number": "02", "title": "Día de Muertos", "timing": "LE NOTTI GRANDI", "color": "blue", "description": "Altari, bande e cimiteri a lume di candela. Nei giorni di lavoro solo la sera; la domenica è tutta libera. ★★ da non perdere · ★ bello se riusciamo. Dove ci sono opzioni, scegline una.", "sections": [], "note": "Taxi da prenotare in anticipo: un autista che aspetti per Etla domenica (il più importante) e i ritorni da Xoxocotlán sabato e lunedì sera. Concorda prima il prezzo: a Oaxaca i taxi non hanno il tassametro. Gli orari possono ancora cambiare: controlla la pagina del turismo statale prima di uscire.", "link": ["Aggiornamenti ufficiali", "https://www.facebook.com/SECTUR.GobOax/"], "table": {"head": ["Quando", "Programma", "Cos’è", "Dove · distanza dallo Zócalo"], "map": "Mappa", "days": [["Venerdì", [["18:30", "Comparsa Divertimuertos", "Sfilata in costume con musica per il centro", "Parte da El Llano, circa 15 minuti a piedi a nord dello Zócalo", "Parque Juárez El Llano Oaxaca"], ["19:30", "Verbena Xandú", "Festa di strada gratuita con musica e bancarelle", "Nello Zócalo, dove finisce la sfilata", "Zócalo Oaxaca"]]], ["Sabato · al mattino si lavora", [["15:30", "Pomeriggio, opzione A · Altari e tapete in centro", "Enorme tappeto di sabbia nel Palacio de Gobierno e mostra di altari nella piazza", "Sullo Zócalo", "Palacio de Gobierno Oaxaca"], ["14:30", "Pomeriggio, opzione B · Atzompa", "Paese della ceramica con una fiera artigiana davanti al cimitero", "Circa 8 km a nord-ovest, 25 minuti in taxi", "Panteón Municipal Santa María Atzompa Oaxaca"], ["15:30", "Pomeriggio, opzione C · Tapetes di Xoxocotlán", "Tappeti di sabbia e mostre nelle strade, poi resti per la veglia (salti la sfilata)", "Circa 8 km a sud, 25–45 minuti in taxi", "Calle Melchor Ocampo Santa Cruz Xoxocotlán"], ["17:30", "★ Gran Comparsa", "La sfilata principale della città: gruppi dei barrios, bande, diablos e catrinas (inizia alle 18)", "Da Juárez o Morelos, 5–10 minuti a piedi", "Avenida Juárez Oaxaca de Juárez"], ["21:00", "★★ Veglia di Xoxocotlán", "Le famiglie vegliano sulle tombe coperte di fiori e candele, con le bande fino alle 2", "Circa 8 km a sud, 30–60 minuti in taxi stasera", "Panteón Xoxocotlán Oaxaca"]]], ["Domenica · tutto il giorno libero", [["11:00", "Giorno, opzione A · Giro dei mercati in centro", "Colazione alla Merced, pan de muerto al Benito Juárez, carne alla griglia al 20 de Noviembre", "La Merced a circa 12 minuti a piedi; gli altri due a due isolati dallo Zócalo", "Mercado Benito Juárez Oaxaca"], ["9:00", "Giorno, opzione B · Mercato di Tlacolula", "Enorme mercato domenicale pieno di fiori per gli altari, pane, barbacoa e mezcal", "Circa 31 km a est, 45 minuti; Teotitlán è di strada", "Mercado de Tlacolula de Matamoros"], ["10:00", "Giorno, opzione C · Concorso di altari a Xoxocotlán", "La gara di altari del paese, poi la comparsa dei bambini dalle 16", "Circa 8 km a sud, 25 minuti in taxi", "Parque Central Santa Cruz Xoxocotlán"], ["12:00", "Giorno, opzione D · Centro con calma", "Tapete del Palacio de Gobierno e mostra di artigianato Casa Hecho en Oaxaca", "In centro, tutto a piedi", "Real Alhóndiga de Antequera Oaxaca"], ["19:00", "★★ Sera, opzione A · Muerteada di San Agustín Etla", "Teatro di strada satirico e in maschera, con le bande, di casa in casa; qualche ora, non tutta la notte", "Circa 17 km a nord, 40–60 minuti in taxi", "San Agustín Etla Oaxaca"], ["18:00", "Sera, opzione B · Muerteada de Chinas + Jalatlaco", "Corteo delle danzatrici tradizionali da El Llano, poi una comparsa di quartiere verso le 20", "10–15 minuti a piedi", "Parque Juárez El Llano Oaxaca"]]], ["Lunedì · al mattino si lavora", [["Dopo il lavoro", "Tapete di Jalatlaco", "Tappeto di sabbia in un bel barrio antico e colorato", "Circa 10 minuti a piedi a nord-est dello Zócalo", "Barrio de Jalatlaco Oaxaca"], ["18:00", "★ Comparsas di Xoxocotlán", "Cortei in costume con le bande, per tutta la notte (La Original dalle 17, Chicos Rebeldes dalle 18)", "Circa 8 km a sud, 25–45 minuti in taxi", "Santa Cruz Xoxocotlán Oaxaca"]]]], "caption": "Día de Muertos, da venerdì a lunedì"}}, {"id": "markets", "number": "03", "title": "Mercati e Jalatlaco", "timing": "POMERIGGI E SERE SEPARATI", "color": "green", "description": "Fumo, cioccolato e vicoli acciottolati. Vieni affamata.", "sections": [["UN POMERIGGIO", [["veinte", "Mercado 20 de Noviembre", "il Pasillo de Humo: scegli la carne e te la grigliano"], ["juarezmkt", "Mercado Benito Juárez", "cioccolato, formaggi, mezcal e chapulines"]]], ["UN ALTRO POMERIGGIO", [["jalatlaco", "Barrio de Jalatlaco", "vicoli acciottolati, murales e piccoli caffè"]]], ["UNA SERA DIVERSA", [["mezcaloteca", "Mezcaloteca", "degustazione guidata di mezcal artigianali", "Prenota."]]], ["UN ALTRO TRAMONTO", [["fortin", "Cerro del Fortín", "collina sopra la città per il tramonto"]]]], "note": "Mercati a pranzo dopo il lavoro; Jalatlaco, Mezcaloteca e Fortín in uscite diverse. Nessun bisogno di fare tutto insieme."}, {"id": "cooking", "number": "04", "title": "Un corso di cucina", "timing": "UNA MATTINA LIBERA DAL LAVORO", "color": "yellow", "description": "Fare la spesa al mercato con una cuoca, poi cucinare tutto da zero.", "sections": [["DAL MERCATO ALLA TAVOLA", [["class", "Mercato e corso di cucina", "salse, tortillas e un mole", "Prenota."]]]], "note": "Prenota in un giorno libero; in alternativa, verifica un corso pomeridiano. Il pasto è incluso nell’esperienza: conferma orari e durata."}, {"id": "food", "number": "05", "title": "Cibo e drink", "timing": "DALLA NOSTRA LISTA SALVATA", "color": "green", "description": "Una lista da cui scegliere, senza dover provare tutto. Abbina un posto alla passeggiata più vicina.", "sections": [["COLAZIONE E PANE", [["boulenc", "Boulenc", "panetteria e brunch a Jalatlaco"], ["bodaega", "Bodæga", "piccolo forno artigianale su Hidalgo"]]], ["PRANZI E CENE LUNGHE", [["levadura", "Levadura de Olla", "la cucina oaxaqueña di casa di Thalía Barrios", "Prenota."], ["humo", "La Cocina de Humo", "il suo menù degustazione cotto sul fuoco a legna", "Prenota con largo anticipo."], ["danzantes", "Los Danzantes", "cucina oaxaqueña contemporanea in un cortile aperto"], ["tierrasol", "Tierra del Sol", "cucina mixteca su una terrazza"], ["copal", "Copal", "ristorante su Alcalá, sopra Santo Domingo"]]], ["UN DRINK LA SERA", [["selva", "Selva", "cocktail con ingredienti di Oaxaca"]]]], "note": "Abbina una cena alla passeggiata più vicina."}, {"id": "montealban", "number": "★", "title": "Monte Albán", "timing": "SCELTA CONSIGLIATA · MEZZA GIORNATA", "color": "yellow", "description": "Una città zapoteca su una collina spianata sopra la valle.", "sections": [["DOPO IL LAVORO O IN UN GIORNO LIBERO", [["alban", "Monte Albán", "rovine, piazze e una vista ampia sulla valle", "Mattina in un giorno libero, oppure primo pomeriggio dopo il lavoro. Pochissima ombra: cappello e acqua."], ["arrazola", "San Antonio Arrazola", "paese vicino degli alebrijes, animali di legno dipinti", "Facoltativo: solo se resta energia."]]]], "note": "Scegli questa gita O Hierve el Agua. Orario indicato: 8–17, ultimo ingresso 16; lascia tempo per viaggio e visita. Arrazola è facoltativa.", "weekend": true, "link": ["Orari ufficiali", "https://lugares.inah.gob.mx/es/node/5803"]}, {"id": "hierve", "number": "★", "title": "Hierve el Agua", "timing": "ALTERNATIVA · UN GIORNO LIBERO", "color": "blue", "description": "Cascate pietrificate e pozze minerali, con un tour o un autista. Al posto di Monte Albán.", "sections": [["LA GITA, CON AL MASSIMO UNA TAPPA IN PIÙ", [["tule", "Árbol del Tule", "uno degli alberi più larghi del mondo", "Facoltativo: scegli al massimo una tappa extra."], ["mitla", "Mitla", "rovine coperte di greche di pietra", "Facoltativo: scegli al massimo una tappa extra."], ["palenque", "Un palenque di mezcal", "distilleria di famiglia dalle parti di Santiago Matatlán", "Facoltativo: scegli al massimo una tappa extra."], ["hierve", "Hierve el Agua", "cascate pietrificate e pozze minerali a picco", "A volte chiude senza preavviso: controlla la settimana prima."]]]], "note": "Riserva un giorno senza lavoro e tieni libero il pomeriggio dopo. Scegli al massimo una tra Tule, Mitla e il palenque; controlla che Hierve sia aperta.", "weekend": true}, {"id": "tlacolula", "number": "+", "title": "Tlacolula e Teotitlán", "timing": "UN’USCITA DI DOMENICA", "color": "pink", "description": "Il mercato e un pranzo bastano. Il paese dei tessitori è facoltativo, solo se ci va.", "sections": [["DI DOMENICA", [["tlacolula", "Mercato di Tlacolula", "uno dei più grandi mercati settimanali della valle", "Solo la domenica."], ["barbacoa", "Barbacoa a pranzo", "capra o agnello cotti lentamente al mercato"], ["teotitlan", "Teotitlán del Valle", "tappeti fatti su telai di legno", "Facoltativo; si può tornare in città dopo pranzo."]]]], "note": "Porta contanti."}];
const optional = [["tilcajete", "San Martín Tilcajete", "un altro paese di alebrijes, a sud della città"], ["temazcal", "Un temazcal", "il bagno di vapore tradizionale, per un pomeriggio di pioggia"], ["tejate", "Tejate", "bevanda fredda di mais e cacao dai mercati"], ["chapulines", "Chapulines", "cavallette tostate con lime e peperoncino, se hai coraggio"]];
const KEY='frolicking-nicky-oaxaca-v2';
let checked={}; let storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) checked=saved; } catch {storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const OPTIONAL_IDS=new Set(['arrazola','tule','mitla','palenque','teotitlan']);
let chosenTrip='montealban';
try {if(localStorage.getItem(KEY+'-trip')==='hierve')chosenTrip='hierve';}catch{}
const tripChoice=document.querySelector('#trip-choice');
tripChoice.value=chosenTrip;
const countedIds=()=>groups.filter(g=>!['montealban','hierve'].includes(g.id)||g.id===chosenTrip).flatMap(g=>g.sections.flatMap(s=>s[1].map(r=>r[0]))).filter(id=>!OPTIONAL_IDS.has(id));
function item(row,extra=false) {const [id,title,desc,note]=row;return `<label class="task${checked[id]===true?' completed':''}"><input type="checkbox" id="${esc(id)}" data-extra="${extra}" ${checked[id]===true?'checked':''}><span class="checkmark" aria-hidden="true"></span><span class="task-copy"><span class="task-title">${esc(title)}</span> <span class="specialty">(${esc(desc)})</span>${note?`<span class="task-note">${esc(note)}</span>`:''}</span></label>`;}
const PHOTOS={"centro": [[["/assets/oax-alcala.jpeg", "Case coloniali colorate lungo l’Andador Macedonio Alcalá", 1400, 1400, "Zitenshi", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Macedonio_de_Alcal%C3%A1.jpg"], ["/assets/oax-jardin.jpeg", "Alti cactus a canne d’organo nel Jardín Etnobotánico accanto all’ex convento", 1400, 1050, "Kaldari", "CC0", "https://commons.wikimedia.org/wiki/File:Jard%C3%ADn_Etnobot%C3%A1nico_de_Oaxaca_06.JPG"]], [["/assets/oax-tlayuda.jpeg", "Una tlayuda con carne, avocado e cipollotti alla griglia", 1400, 1050, "Gomez.erick", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:TLAYUDA.jpg"], ["/assets/oax-chocolate.jpeg", "Il cacao macinato nei molinos di una bottega di cioccolato Mayordomo", 930, 1400, "LBM1948", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Oaxaca_de_Ju%C3%A1rez,_23.jpg"]]], "muertos": [], "markets": [[["/assets/oax-mercado.jpeg", "Il fumo delle griglie nel corridoio della carne del Mercado 20 de Noviembre", 1400, 937, "ProtoplasmaKid", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Mercado_20_de_noviembre_-_Oaxaca_de_Ju%C3%A1rez_-_10.jpg"]], []], "cooking": [[["/assets/oax-mole.jpeg", "Un piatto di mole negro con riso", 1400, 1050, "ProtoplasmaKid", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Mole_negro_de_Oaxaca_con_arroz.jpg"]]], "montealban": [[["/assets/oax-montealban.jpeg", "La Gran Plaza di Monte Albán sulla cima spianata della collina sopra la valle", 1400, 1060, "Infrogmation", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Monte_Alb%C3%A1n_Oaxaca_1976_01.jpg"]]], "hierve": [[["/assets/oax-hierve.jpeg", "La cascata pietrificata e bianca di Hierve el Agua lungo un versante verde", 1400, 1050, "Adrián Cerón", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Hierve_el_agua.JPG"], ["/assets/oax-mitla.jpeg", "Muri decorati a greche di pietra intorno a un cortile a Mitla", 1400, 933, "DavidConFran", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Patio_Grupo_Norte.JPG"]]], "tlacolula": [[["/assets/oax-tlacolula.jpeg", "Bancarelle di frutta, fiori e pane al mercato domenicale di Tlacolula", 1400, 933, "Bluerasberry", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tlacolula_Market_230122_62.jpg"], ["/assets/oax-teotitlan.jpeg", "Un tessitore al telaio di legno a Teotitlán del Valle, con i tappeti finiti alle spalle", 1280, 854, "Axel Alvarado Chávez", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tejido_de_Tapetes_Artesanales_en_Telar._Teotitl%C3%A1n_Del_Valle,_Oaxaca.jpg"]]], "food": [[], [["/assets/oax-fire.jpeg", "Una donna mescola un grande pentolone di mole sul fuoco a legna", 1050, 1400, "Diego Emiliano Jaramillo Navarro", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Do%C3%B1a_Mari,_la_Reina_del_Mole.jpg"], ["/assets/oax-tlayuda-grill.jpeg", "Un venditore di tlayudas alla griglia per strada, di sera a Oaxaca", 787, 1400, "Alex Haulman", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tlayuda_vendor_in_Oaxaca_City.jpg"]], []]};
const fig=([src,alt,w,h,by,lic,url])=>`<figure class="fn-v-photo"><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></a>${by?`<figcaption>Foto: ${by} · <a href="${url}" target="_blank" rel="noopener noreferrer">${lic}</a></figcaption>`:''}</figure>`;
const muertosTable=t=>{const pick=(()=>{const d=new Date();const k=(d.getMonth()+1)*100+d.getDate();return {1031:1,1101:2,1102:3}[k]??0;})();return `<div class="fn-plan-tabs" role="tablist" aria-label="${esc(t.caption)}">${t.days.map(([day],i)=>`<button type="button" role="tab" id="fn-plan-tab-${i}" aria-controls="fn-plan-day-${i}" aria-selected="${i===pick}" tabindex="${i===pick?0:-1}">${esc(day.split(' · ')[0])}</button>`).join('')}</div>${t.days.map(([day,rows],i)=>`<div class="fn-plan-panel" role="tabpanel" id="fn-plan-day-${i}" aria-labelledby="fn-plan-tab-${i}"${i===pick?'':' hidden'}>${day.includes(' · ')?`<p class="fn-plan-sub">${esc(day.split(' · ').slice(1).join(' · '))}</p>`:''}<ol class="fn-plan-stops">${rows.map(([when,plan,what,where,q])=>`<li${/★/.test(plan)?' class="fn-plan-star"':''}><span class="fn-plan-when">${esc(when)}</span><div><p class="fn-plan-name">${esc(plan)}</p><p class="fn-plan-what">${esc(what)}</p><p class="fn-plan-where">${esc(where)} <a class="fn-plan-map" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(q)}" target="_blank" rel="noopener noreferrer">${esc(t.map)}</a></p></div></li>`).join('')}</ol></div>`).join('')}`;};
let rowN=0;
document.querySelector('#itinerary').innerHTML=groups.map(g=>`<section id="${g.id}" class="outing fn-split ${g.color} ${g.weekend?'weekend':''}" aria-labelledby="title-${g.id}"><div class="outing-heading"><span class="number" aria-hidden="true">${g.number}</span><div><p class="eyebrow">${g.timing}</p><h2 id="title-${g.id}">${g.title}</h2><p class="section-desc">${g.description}</p></div><span class="group-count" id="count-${g.id}" aria-label="Completamento della sezione"></span></div>${g.table?`<div class="fn-plan-wrap">${muertosTable(g.table)}</div>`:''}<div class="outing-body fn-split-body"${g.sections.length?'':' hidden'}>${g.sections.map(([title,rows],si)=>{const ps=(PHOTOS[g.id]||[])[si]||[];const card=`<div class="task-group"><h3>${title}</h3>${rows.map(r=>item(r,OPTIONAL_IDS.has(r[0]))).join('')}</div>`;return ps.length?`<div class="fn-v-row${rowN++%2?' fn-v-rev':''}"><div class="fn-v-side">${ps.map(fig).join('')}</div>${card}</div>`:card;}).join('')}</div><div class="outing-note"><p>${g.note}</p>${g.link?`<a href="${g.link[1]}" target="_blank" rel="noopener noreferrer">${g.link[0]} ↗︎</a>`:''}</div></section>`).join('');
document.querySelectorAll('.fn-plan-tabs').forEach(list=>{const tabs=[...list.querySelectorAll('[role=tab]')];const show=(tab,focus)=>{tabs.forEach(b=>{const on=b===tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;document.getElementById(b.getAttribute('aria-controls')).hidden=!on;});if(focus)tab.focus();};tabs.forEach((b,i)=>{b.addEventListener('click',()=>show(b));b.addEventListener('keydown',e=>{const n={ArrowRight:i+1,ArrowLeft:i-1,Home:0,End:tabs.length-1}[e.key];if(n===undefined)return;e.preventDefault();show(tabs[(n+tabs.length)%tabs.length],true);});});});
document.querySelector('#optional-list').innerHTML=optional.map(r=>item(r,true)).join('');
function update(announce=false){const mainIds=countedIds();const done=mainIds.filter(id=>checked[id]===true).length;const percent=Math.round(done/mainIds.length*100);document.querySelector('#progress-count').textContent=done;document.querySelector('#progress-total').textContent=`su ${mainIds.length} posti e momenti`;document.querySelector('#percent').textContent=percent+'%';document.querySelector('#progress').value=percent;document.querySelector('#progress').textContent=percent+'%';groups.forEach(g=>{const inactive=['montealban','hierve'].includes(g.id)&&g.id!==chosenTrip;const ids=g.sections.flatMap(s=>s[1].map(r=>r[0])).filter(id=>!OPTIONAL_IDS.has(id));document.querySelector('#count-'+g.id).hidden=!ids.length;document.querySelector('#count-'+g.id).textContent=inactive?"Alternativa: non conta nella checklist":`${ids.filter(id=>checked[id]===true).length} / ${ids.length}`;});const extra=[...optional.map(r=>r[0]),...OPTIONAL_IDS].filter(id=>checked[id]===true).length;document.querySelector('#extra-count').textContent=`${extra} ${extra===1?'tappa facoltativa fatta':'tappe facoltative fatte'}`;document.querySelector('#save-note').textContent=storageOK?'Progressi salvati su questo dispositivo.':'Le spunte funzionano qui, ma in questo browser il salvataggio non è disponibile.';if(announce)document.querySelector('#announcement').textContent=`${done} su ${mainIds.length} voci principali completate. ${extra} tappe facoltative fatte.`;}
tripChoice.addEventListener('change',()=>{chosenTrip=tripChoice.value;try{localStorage.setItem(KEY+'-trip',chosenTrip);}catch{}update(true);});
function persist(){try{localStorage.setItem(KEY,JSON.stringify(checked));storageOK=true;}catch{storageOK=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('.task input'))return;checked[e.target.id]=e.target.checked;e.target.closest('.task').classList.toggle('completed',e.target.checked);persist();update(true);});
window.addEventListener('storage',e=>{if(e.key===KEY+'-trip'){chosenTrip=e.newValue==='hierve'?'hierve':'montealban';tripChoice.value=chosenTrip;update();return;}if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue||'{}');checked=next&&typeof next==='object'&&!Array.isArray(next)?next:{};}catch{checked={};}document.querySelectorAll('.task input').forEach(el=>{el.checked=checked[el.id]===true;el.closest('.task').classList.toggle('completed',el.checked);});update();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{checked={};persist();document.querySelectorAll('.task input').forEach(el=>{el.checked=false;el.closest('.task').classList.remove('completed');});update(true);dialog.close();});
update();
